WITH review_input (
  professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (535::BIGINT, 'Si se estresan fácilmente, no matriculen con el. Es un dolor tanto a la libreta, la vestimenta, el cabello, la hora de llegada y cualquier cosa que se hace en clase. Busca la más mínima cosa para poner un 0 en la practica de la semana. Personalidad seca y muy seria, no tiene paciencia.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Asistencia obligatoria']::TEXT[], '2026-07-21T00:00:00+00:00'::TIMESTAMPTZ, '306a872534405e98a59933e69542fe5a34b9573dbf08001f82654c053cbfd25d'::TEXT, ARRAY[567]::BIGINT[]),
    (535::BIGINT, 'Es demasiado concho, no sabe responder de forma amable y en lugar de ayudar lo manda a uno a volar. Da miedo, y el ambiente en la clase es demasiado tenso. Pide los informes al final de TODAS las clases, aunq la práctica sea larguísima. Y no usa el TECdigital ent ud tiene que calcular su nota solo.'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2026-07-05T00:00:00+00:00'::TIMESTAMPTZ, 'bef93ac52b46cd7c5d3348174ee80b41f1ede68eb2d6dfe897a53d8f39f56101'::TEXT, ARRAY[567]::BIGINT[]),
    (535::BIGINT, 'Si no tiene interés y le gusta salir rápido de todo, meta con él. Muchos lo critican, pero todos en mi clase pasaron. No falte nunca con el cuadro de constantes, le pone 0. Quices fáciles todas las semanas, si es medio duro en los informes pero se pueden hacer con teléfono (aunque el mismo día).'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura']::TEXT[], '2026-07-03T00:00:00+00:00'::TIMESTAMPTZ, '8c5a2a8c17c31d66a62e0a3ffd5d42f0e81ae287fd63acd897b4ba318011e8c3'::TEXT, ARRAY[567]::BIGINT[]),
    (535::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-06-03T00:00:00+00:00'::TIMESTAMPTZ, 'a356cdc7e5b303f977065aa505a35dd00ef995bbb751434c5f45ea2237a990b3'::TEXT, ARRAY[613, 567]::BIGINT[]),
    (535::BIGINT, 'No matriculen con él. Se le nota que no le gusta ser profesor, entonces no explica bien la teoría ni ayuda en las prácticas del lab, básicamente lo deja a uno adivinando. Tampoco le gusta que le pregunten (?) y su actitud es horrible. En serio, todo mal con este viejo.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('20','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2026-04-23T00:00:00+00:00'::TIMESTAMPTZ, 'b05b03e91d0d585d13f91303993fab8ab6b37ba589cd6f435f6aa8d54b12cdc3'::TEXT, ARRAY[613, 567]::BIGINT[]),
    (535::BIGINT, 'Pésima actitud, no se les puede preguntar nada porque se enoja. Si usted de verdad quiere aprender, estudie mucho por su cuenta, porque no da tiempo de hacer los informes, ni un minuto extra. No califica duro, el curso es pasable pero sin duda su actitud es NEFASTA, no le interesa que usted aprenda'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria']::TEXT[], '2026-03-25T00:00:00+00:00'::TIMESTAMPTZ, '44371c64f482e7c5190ce4522b35eb6cecb155ad36e5feace3a83dbcc6d9cca5'::TEXT, ARRAY[613, 567]::BIGINT[]),
    (535::BIGINT, 'Pesimo, la clase introductoria me basto para no volver más, cualquier persona que lo recomiende es una multicuenta suya'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Exámenes retadores']::TEXT[], '2026-02-27T00:00:00+00:00'::TIMESTAMPTZ, '6eecf03e7e7de5b0025643f2b36379b6ce00d89d2d472678abb016c246b90479'::TEXT, ARRAY[613, 567]::BIGINT[]),
    (535::BIGINT, 'Es muy sacastico y a veces es cruel porque quiere todo perfecto a la primera. Aún así es fácil de pasar y no se pone en tantos detalles al revisar pero si recomendaría que busque otra opción si quiere sentirse en un ambiente menos hostil.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria']::TEXT[], '2026-01-19T00:00:00+00:00'::TIMESTAMPTZ, 'cd012a954f72d0a53edbad47b166229ba86e2d597443776102e0a3de5487cd77'::TEXT, ARRAY[567]::BIGINT[]),
    (535::BIGINT, 'Irrespetuoso, humilla a los estudiantes y no aprendes nada.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-01-07T00:00:00+00:00'::TIMESTAMPTZ, 'c2b9976ce2e2a1c30c3cf4d9c86bc662490b82d02838a7ac45886801bca6aa04'::TEXT, ARRAY[613, 567]::BIGINT[]),
    (535::BIGINT, 'Como todos los profesores de lab exige libreta, pero no pide todo el marco teórico, deben estar todos los cuadros, aunque me sorprendió que en lab II me exigieron detalles que este profesor no pedía. En algunos quices le pedí que me explicara cosas que yo tenía mal pero al final estaban bien.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'La participación importa', 'Asistencia obligatoria']::TEXT[], '2025-12-06T00:00:00+00:00'::TIMESTAMPTZ, '9086d572fd0187d69acf8b64c545ad987cb5b573fdd105487e6cdf6c9a9febe5'::TEXT, ARRAY[567]::BIGINT[]),
    (535::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2025-07-23T00:00:00+00:00'::TIMESTAMPTZ, '9be3f578d7ec26f321fd204838955c710b4d94cbaa8298bce8b315bf84214d63'::TEXT, ARRAY[613, 567]::BIGINT[]),
    (535::BIGINT, 'Excelente profesor, super amable y amistoso!! (si pueden no matriculen con él) pero es un gran profesor!!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Brinda apoyo']::TEXT[], '2025-05-08T00:00:00+00:00'::TIMESTAMPTZ, 'ab841062dd3512cb57b3ba7f806275ff4c22a40d34a28b2b2ce395a56f0228b6'::TEXT, ARRAY[613, 567]::BIGINT[]),
    (535::BIGINT, 'Si ya el lab de química es pesado por defecto, este profe no ayuda. Es muy detallisata con la bitácora y los informes. Le va bajar puntos por cualquier error. El señor exige mucha disciplina y puntualidad. La verdad matricule con otra persona si puede.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Deja trabajos largos']::TEXT[], '2024-12-02T00:00:00+00:00'::TIMESTAMPTZ, '3f9f1417580e4e1adb2b822bddaf050b4a638e59f9d6c388354f30e41be7259f'::TEXT, ARRAY[567]::BIGINT[]),
    (535::BIGINT, 'Horrible profesor, no sabe ni lo que está hablando, se confunde él solo y al """"""ayudar"""""" solo le dice que piense y se va. No le gusta enseñar y ni revisar sabe. Ademas dice haiga, me sangran los oidos cada vez más'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2024-10-16T00:00:00+00:00'::TIMESTAMPTZ, 'd98456d4789601b28e5015e73581dbe9df3fe4409a56437baa6866f295869756'::TEXT, ARRAY[567]::BIGINT[]),
    (535::BIGINT, 'Un asco de profesor, no se como puede dar clases, ese mae no le gusta ser profesor, otro ladrón en el sector público robando salario'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('10','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria']::TEXT[], '2024-09-13T00:00:00+00:00'::TIMESTAMPTZ, '74a22e21a015ed9872a18e718ab89b4269c0fb15a826e0756c2ee459ee7dc40a'::TEXT, ARRAY[613, 567]::BIGINT[]),
    (535::BIGINT, 'Aires de que no le gusta ser profesor. Es grosero cuando se le pregunta algo. Explica poco y se enreda al hablar o uno queda confundido. Califica los informes muy duro. NO tenerlo como primera opción.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria']::TEXT[], '2024-06-13T00:00:00+00:00'::TIMESTAMPTZ, '5c754dd2968d7994ce9db46f28281a76f0233ac095f9fff59b8a4231feeeb2ff'::TEXT, ARRAY[567]::BIGINT[]),
    (535::BIGINT, 'No lo recomiendo para nada, su actitud es impertinente y sus clases pueden resultar más estresantes por su actitud irrespetuosa con los estudiantes, NO matriculen con él, NO van a aprender nada y NO van a ser clases agradables.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-06-12T00:00:00+00:00'::TIMESTAMPTZ, 'fd0d940eab08f52e0bd73c19526278a1d7a5423f34df76e80b33ca157ea79af9'::TEXT, ARRAY[613, 567]::BIGINT[]),
    (535::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2024-04-22T00:00:00+00:00'::TIMESTAMPTZ, '22d7957b21ae6ff0be547029ca638c3e7f7e2dae11ab95588622094b10f35dd9'::TEXT, ARRAY[567]::BIGINT[]),
    (535::BIGINT, 'El mae suele explicar un poco la materia pero no se le entiende, es buena nota si usted es activo y participa, si se jala tortas o comete torpezas téngalo por seguro que lo agarra de piso el resto del semestre. Con que estudie bastante y cumpla con la libreta pasa fácil.'::TEXT, 8.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Asistencia obligatoria']::TEXT[], '2023-11-23T00:00:00+00:00'::TIMESTAMPTZ, 'b9abef26795a5075f756c72103a2a57f30d5f29ad33acbd69081101eaff8eb26'::TEXT, ARRAY[567, 613]::BIGINT[]),
    (535::BIGINT, 'META CON ESTE PROFE SI ES SU ÚLTIMA OPCION, ES MUY SARCASTICO Y EXPLICA SOLO LO NECESARIO,METE MIEDO COMO SI FUERA EL MEJOR, LOS QUIZZES SON VIRTUALES Y FACILES, PERO A ÉL LE CUESTA MUCHO DARSE A ENTENDER NO EXPLICA CLARO'::TEXT, 8.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria']::TEXT[], '2023-06-26T00:00:00+00:00'::TIMESTAMPTZ, '72b430c498248a4edd2523094a975da2231e2d07e6d8d9eefa73413c648eb165'::TEXT, ARRAY[567]::BIGINT[]),
    (535::BIGINT, 'Califica como quiere, ni intente apelar que mas sale debiendo puntos. Es de saber llevar la clase, es estricto pero no se pone a revisar detalladamente, es tosco para tratar a los estudiantes pero si entiende la practica ya con eso pasa. Mete miedo pero al final no es tan complicado'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2022-12-22T00:00:00+00:00'::TIMESTAMPTZ, 'abc47f74b59d05475ef77f5a5fe1eff780c142e951b8b1cd270eb6c81f2ed25b'::TEXT, ARRAY[613]::BIGINT[]),
    (535::BIGINT, 'Califica a su antojo, es poco empático y sarcástico, si aprende a llevarse con él no la pasa mal, en general no es mal profe, pero quizá no genera el mejor ambiente en clases. Explica lo necesario nada más, si le hace una pregunta sí le contesta, pero no necesariamente para responderle la pregunta.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2022-12-07T00:00:00+00:00'::TIMESTAMPTZ, '1b7f202f48a26ef4e2c4678237d1d291ad6bacb0f8a58fd736e6b99f7b863b7a'::TEXT, ARRAY[613]::BIGINT[]),
    (535::BIGINT, 'Las clases por lo general son cortas, se debe poner mucha atención, explica lo necesario.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Pocos exámenes']::TEXT[], '2022-06-03T00:00:00+00:00'::TIMESTAMPTZ, '9f33784e3ffabf393e817532a3b5551d247669417a768f462919dfc60bff0729'::TEXT, ARRAY[567]::BIGINT[]),
    (535::BIGINT, 'Es un excelente profesor!! Explica súper claro; lo necesario y conciso. Sabe mucho del tema!! Siempre está atento a aclarar dudas de cualquier tipo. La retroalimentación que da en los trabajos es valiosa!! Las notas siempre están actualizadas. Volvería a tomar clases con él!! Lo recomiendo 100%!!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-11-16T00:00:00+00:00'::TIMESTAMPTZ, 'b782982f1b878d41c23e2d0156762a03d1856a7e53510b58f2a9c2dead21e778'::TEXT, ARRAY[613]::BIGINT[]),
    (535::BIGINT, 'Las clases con el profe son cortas y concisas, no explica de más solo lo básico y no brinda ayuda para realizar los informes. Verdaderamente no es tan mal profesor pero tampoco pero no va a ser su favorito, puede encontrar mejores profes.'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa']::TEXT[], '2021-07-12T00:00:00+00:00'::TIMESTAMPTZ, '4487c582702cf3d068d63d825989b870d367f06feae9fda61cc15435af7925bb'::TEXT, ARRAY[567]::BIGINT[]),
    (535::BIGINT, 'No le gusta que se le pregunten cosas muy obvias. Los quices que hace son bastante fáciles, califica justo los informes. No es el mejor profe pero tampoco el peor. El curso se pasa fácil pero no se aprende mucho.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-06-23T00:00:00+00:00'::TIMESTAMPTZ, '366a1100051bfd750997cf65290c75780738e3cdd3a2f4bcf9ea8adf4c235cbd'::TEXT, ARRAY[567]::BIGINT[]),
    (535::BIGINT, 'Al inicio creí que era un profe malo y aborrecida, ya después le agarre el sentido a sus clases y creo que da las clases cortas pero explica lo nesesario, las clases dependen de sí anda mal humorado, pero en términos generales me parece un buen profe,NO PREGUNTE COSAS OBVIAS'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Respetado por los estudiantes']::TEXT[], '2021-04-16T00:00:00+00:00'::TIMESTAMPTZ, '3836a8896743f38db0138f8e7169996bf94b8b3e6376fa10f60823a3f16e3402'::TEXT, ARRAY[613, 567]::BIGINT[]),
    (535::BIGINT, 'En la modalidad presencial si era algo exigente con las normas y las actas... en la virtualidad las clases son más tranquilas, explica el tema y si no hay dudas las clases duran 20min, recuerde siempre cumplir con los quices en el GAAP q son fáciles de olvidar.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros']::TEXT[], '2020-09-03T00:00:00+00:00'::TIMESTAMPTZ, '2a4dfa9163460f1877301b1f1f662be636a7dbf80fd5a532b94921adab876af8'::TEXT, ARRAY[567]::BIGINT[]),
    (535::BIGINT, 'Califica super rudo los informes si uno no pone lo que el quiere que uno explique, por cualquier cosa le baja un monton de puntos. Ponga atencion y no haga preguntas muy obvias'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-24T00:00:00+00:00'::TIMESTAMPTZ, 'e9c7030ceb0739d9350caf30029e8b405928eba6484b218ee336d63383c9c31a'::TEXT, ARRAY[613]::BIGINT[]),
    (535::BIGINT, 'El profe no esta siempre de buen humor, pero es bueno, explica claro, y le interesa que usted aprenda. Si le va a hacer consultas tontas mejor no las haga jaja porque ese profe se toma muy en serio todo. Los quices son faciles, califica estricto en informes con lo que se pide como todos los de lab'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-22T00:00:00+00:00'::TIMESTAMPTZ, '352d2459115ab26f43291ff60d6783b2b9ae90d03e63e22da23cc918e936892d'::TEXT, ARRAY[613]::BIGINT[]),
    (535::BIGINT, 'El profe en sí no es malo solo que cuando da la clase es malhumorado y si usted le va a preguntar algo que ya se vió en las clases pasadas le responde mal, por lo que llevar la materia al día es importante. Si usted es alguien perezoso que no lleva las cosas al día, mejor matricule con otro profe.'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases largas']::TEXT[], '2020-08-17T00:00:00+00:00'::TIMESTAMPTZ, '5c90a6b449b7d104f70fe18d6dc32b3f435f4973263503d101ca09abc7924bc8'::TEXT, ARRAY[567]::BIGINT[]),
    (535::BIGINT, 'Se debe tener la materia al día para la realización un buen informe. Los quices son fáciles. El profesor siempre brinda apoyo, pero hay que demostrarle el interés que se tiene en el curso.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2020-08-17T00:00:00+00:00'::TIMESTAMPTZ, '25c6ef0394422ca85e6ca7d927888a9545eacceaa987b1b92391582170ec2f4c'::TEXT, ARRAY[613]::BIGINT[]),
    (535::BIGINT, 'Las clases son aburridas y el profe puede ser un poco malhumorado. Los quices son fáciles, de dos o tres preguntas pero hay que repasar bien la libreta para responderlas y siempre llevar todo al día, porque no da tiempo para presentarlo despúes. En sí la clase es fácil, y el profe no es malo.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria']::TEXT[], '2020-07-31T00:00:00+00:00'::TIMESTAMPTZ, '90b50ad337c0e59a90c5c836a21e559fbe2960403c8893d73ed4e3b6b9a025ee'::TEXT, ARRAY[567]::BIGINT[]),
    (535::BIGINT, 'Hace aburridas hasta las clases que deberían ser interesantes, pero igual no es mal profe. Es regular'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-02-05T00:00:00+00:00'::TIMESTAMPTZ, '13591d0b3f99d268d22ae5632bb3647eaafb3d7c2b5e04ad9bc8efaee91c01aa'::TEXT, ARRAY[613]::BIGINT[]),
    (535::BIGINT, 'No le hagan caso a la calificación del profe, el mae es muy buena nota y le ayuda cuando tiene dudas. Los quices son muy fáciles y califica muy suave. Explica de lo más bien. Lo único con lo que tienen que tener cuidado es llevar la libreta completa o sino tienen 0 es todo el trabajo en clase.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-10-02T00:00:00+00:00'::TIMESTAMPTZ, '2abc3e3c3e7b90086f1b74aa576ad5138fa591c48e9bfab37ee548d1337f4893'::TEXT, ARRAY[613]::BIGINT[]),
    (535::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria']::TEXT[], '2019-08-05T00:00:00+00:00'::TIMESTAMPTZ, 'a217f7d636e9965fd849abc9b3dcf69cb94a2f0c6c6df779b361682dbd03618d'::TEXT, ARRAY[567]::BIGINT[]),
    (535::BIGINT, 'El profesor explica muy bien la materia pero a la hora de dudas es complicado obtener su atención. Repasar siempre la libreta y las prácticas antes de cada clase.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria']::TEXT[], '2019-06-25T00:00:00+00:00'::TIMESTAMPTZ, '777d4805d6202a103cfd2bdc7ef3d33ac9931601202f77a8c63c83daa42e7933'::TEXT, ARRAY[567]::BIGINT[]),
    (535::BIGINT, 'EL PEOR!! NO MATRICULEN CON ÉL!!!. Quita puntos a lo loco, es todo tonto para calificar, no se le entiende cuando explica la practica, no evacua dudas y es demasiado cae mal. Lleven las constantes físicas!!! porque de lo contrario les pone cero en la libreta. Yo la vi fea para pasar'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'c2cec78fc119f2240e0b9bd73e37de6275101e164df7cca6c8f1f358af730203'::TEXT, ARRAY[567]::BIGINT[]),
    (535::BIGINT, 'SIEMPRE lleve la libreta completa, los quices son faciles y cortos, siempre explica el procedimiento y ayuda dependiendo del humor. Mucha gente en mi clase se quedó pasamos 4 solo'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Asistencia obligatoria', 'Exámenes retadores']::TEXT[], '2019-06-24T00:00:00+00:00'::TIMESTAMPTZ, '1df24a31b5b8e75a35666c8960b4d3e291fbf00d5e92d8cc512aae4c8d91b0a2'::TEXT, ARRAY[567]::BIGINT[]),
    (535::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-04-12T00:00:00+00:00'::TIMESTAMPTZ, '2c4f2785ea625106cfde49645de350dd3aa9755a1201d857fbc1b2a934a376c0'::TEXT, ARRAY[567]::BIGINT[]),
    (535::BIGINT, 'No sé porque la calificación tan baja de este profe. Es un excelente profe con el hecho de que explica clarísimo la materia, revisa super suave y los quices son demasiado fáciles. A veces si es un poco serio, pero nada fuera de lo normal. Matricule sin miedo con él. Es un éxito.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-13T00:00:00+00:00'::TIMESTAMPTZ, 'da4e59fdfbc715120c3598e3a00b23f112c69518783e00d55776944e890852fd'::TEXT, ARRAY[613]::BIGINT[]),
    (535::BIGINT, 'Califica muy suave, nunca revisa la libreta, y si es serio pero tampoco para tanto, de hecho le ayuda bastante si ve que uno le pone.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-08-28T00:00:00+00:00'::TIMESTAMPTZ, '18016c81fb77cb5b2aa11c76a4e0aa6235ca91c46eca5dbd122484ef97f7bf8b'::TEXT, ARRAY[613]::BIGINT[]),
    (535::BIGINT, 'Nunca, nunca, nunca haga mal la Libreta, es muy estricto con eso, califica maso y explica una vez antes de todo y si cuesta un toque hacer que lo atienda a uno'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2018-07-01T00:00:00+00:00'::TIMESTAMPTZ, '3386f6da949aa13bca70049db108999b443f0d60cebebebffac71e26891dcd0f'::TEXT, ARRAY[567]::BIGINT[]),
    (535::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Exámenes retadores']::TEXT[], '2018-06-15T00:00:00+00:00'::TIMESTAMPTZ, '380a401c4050222724f786c63ca637c683b2fc954a598edb97be37ba5773ec59'::TEXT, ARRAY[567]::BIGINT[]),
    (535::BIGINT, 'Se para'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-10-23T00:00:00+00:00'::TIMESTAMPTZ, '505279bc22e10451d9ae22be37aa246354a4532de1c34a626d64ada050420c30'::TEXT, ARRAY[613]::BIGINT[]),
    (535::BIGINT, 'Muy serio, y lo deja a uno trabajando solo, cuando se necesita no esta presente, lo teórico casi no lo explica, pero califica como debe ser, y si uno hace la libreta a conciencia todo es regalado.'::TEXT, 10.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Clases largas']::TEXT[], '2017-06-30T00:00:00+00:00'::TIMESTAMPTZ, '91011889b86002e7ea947d69a23e8e100ca7cd1f6be9327a3a5c366862b3d171'::TEXT, ARRAY[613, 567]::BIGINT[]),
    (535::BIGINT, 'Un poco serio al principio, trata de meter miedo, luego es vacilón, llevé con el los dos laboratorios de química básica, sabe demasiado, es tecnólogo de alimentos y buena nota.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2017-01-18T00:00:00+00:00'::TIMESTAMPTZ, '1ea159d89f0808ce4a15219be3a2926a88b00f0844eef53a632f374d310ce01e'::TEXT, ARRAY[613]::BIGINT[]),
    (535::BIGINT, 'Él mae no explica mucho la teoría pero el curso es pasable con él y califica suavitel sí lo recomiendo'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria']::TEXT[], '2016-12-06T00:00:00+00:00'::TIMESTAMPTZ, '09d7998c20239ae57bc15936044c0420aa52cb461a230f49e422c4e4f018c5df'::TEXT, ARRAY[613]::BIGINT[]),
    (535::BIGINT, 'Amargadillo, un poco HP pero explica bien, quices muy muy faciles (cuestionario previo casi siempre), califica muy muy suave, todos pasan, da risa mucha risa explicaciones raras donde compara con orgias y su clasico "si lo botan se joden". Buen profe metan sin miedo pasan de una no se arrepentiran.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Asistencia obligatoria', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'cc9caf9645a698fa0afd312a99dc236abfa7b1a0001b0fa2093ceb4746c0742d'::TEXT, ARRAY[613]::BIGINT[]),
    (535::BIGINT, 'Él profe al principio es serio pero después ya agarra confianza con los estudiantes califica suave'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'f43e28bb5287c6e6762b487b78118ca78897d07636d9c6cf74fe2374d07719a4'::TEXT, ARRAY[567]::BIGINT[]),
    (535::BIGINT, 'No explica muy bien. Es muy amargado y duro calificando No usa en lo absoluto el tecdigital'::TEXT, 8.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-07T00:00:00+00:00'::TIMESTAMPTZ, '08bb5741360ed44307d20e00476469acf722b45fdcf379fab4fd2308d326a94a'::TEXT, ARRAY[567]::BIGINT[]),
    (535::BIGINT, 'Es poco claro, no es muy simpático al principio del curso sin embargo cuando le agarra confianza se vuelve más amable y califica bien'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-18T00:00:00+00:00'::TIMESTAMPTZ, 'ee942a8709dc59935773c649f7b90e04d808eb6ad7a02011db2f5d17bdaafff7'::TEXT, ARRAY[613, 567]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
